import {config} from './config.js';
const $=s=>document.querySelector(s), names={HR01:'Neueintragung',HR02:'Mutation',HR03:'Löschung'};
let notices=[], type='all', limit=30, client=null, user=null, saved=new Set(), mode='login', recovery=false;
const formatDate=s=>new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(s+'T12:00:00'));
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function error(message){$('#error').textContent=message;$('#error').hidden=!message}
function render(){const q=$('#search').value.trim().toLocaleLowerCase('de');const from=$('#from').value,to=$('#to').value,seat=$('#seat').value;const rows=notices.filter(n=>(type==='all'||(type==='saved'?saved.has(n.id):n.type===type))&&(!from||n.date>=from)&&(!to||n.date<=to)&&(!seat||n.seat===seat)&&(!q||[n.name,n.uid,n.text,n.seat].join(' ').toLocaleLowerCase('de').includes(q)));$('#result-count').textContent=`${rows.length} Meldung${rows.length===1?'':'en'}`;$('#notices').replaceChildren();$('#empty').hidden=rows.length>0;$('#more').hidden=rows.length<=limit;for(const n of rows.slice(0,limit)){const article=node('article',undefined,'notice');const top=node('div',undefined,'notice-top');top.append(node('span',names[n.type]||n.type,'kind '+n.type),node('time',formatDate(n.date)));const heading=node('h3',n.name||n.title);const identity=node('div',[n.seat,n.uid].filter(Boolean).join(' · '),'identity');const details=node('details');details.append(node('summary','Publikation lesen'),node('p',n.text,'notice-text'));const bottom=node('div',undefined,'notice-bottom');const link=node('a','Offizielles SHAB-PDF ↗');link.href=n.pdf;link.target='_blank';link.rel='noopener noreferrer';const save=node('button',saved.has(n.id)?'✓ Gemerkt':'+ Merken','save');save.setAttribute('aria-pressed',String(saved.has(n.id)));save.setAttribute('aria-label',`${n.name}: ${saved.has(n.id)?'aus Merkliste entfernen':'merken'}`);save.onclick=()=>toggleSave(n,save);bottom.append(link,save);article.append(top,heading,identity,details,bottom);$('#notices').append(article)}}
async function toggleSave(n,button){if(!user||!client){openAuth();return}button.disabled=true;try{const result=saved.has(n.id)?await client.from('bookmarks').delete().eq('user_id',user.id).eq('publication_id',n.id):await client.from('bookmarks').insert({user_id:user.id,publication_id:n.id});if(result.error)throw result.error;saved.has(n.id)?saved.delete(n.id):saved.add(n.id);error('');render()}catch{error('Die Merkliste konnte nicht gespeichert werden. Bitte erneut versuchen.')}finally{button.disabled=false}}
async function loadBookmarks(){saved=new Set();if(client&&user){const {data,error:e}=await client.from('bookmarks').select('publication_id');if(e)error('Deine Merkliste konnte nicht geladen werden.');else saved=new Set(data.map(x=>x.publication_id))}render()}
function openAuth(){const configured=!!client;$('#auth-title').textContent=user?'Dein Konto':configured?'Willkommen zurück.':'Anmeldung folgt.';$('#auth-info').textContent=user?`Angemeldet als ${user.email}`:configured?'Speichere interessante Meldungen in deiner persönlichen Merkliste.':'Die Meldungen sind bereits verfügbar. Die Anmeldung und persönliche Merkliste werden noch eingerichtet.';$('#auth-form').hidden=!configured||!!user;$('#switch-auth').hidden=!configured||!!user;$('#reset-password').hidden=!configured||!!user;$('#sign-out').hidden=!user;$('#auth-message').textContent='';$('#auth-dialog').showModal()}
$('#account').onclick=openAuth;$('#close-auth').onclick=()=>$('#auth-dialog').close();$('#sign-out').onclick=async()=>{const {error:e}=await client.auth.signOut();if(e){$('#auth-message').textContent='Abmelden fehlgeschlagen. Bitte erneut versuchen.';return}$('#auth-dialog').close()};
$('#switch-auth').onclick=()=>{mode=mode==='login'?'signup':'login';$('#submit-auth').textContent=mode==='login'?'Anmelden':'Konto erstellen';$('#auth-title').textContent=mode==='login'?'Willkommen zurück.':'Dein eigener Registerblick.';$('#switch-auth').textContent=mode==='login'?'Noch kein Konto? Registrieren':'Schon ein Konto? Anmelden';$('#password').autocomplete=mode==='login'?'current-password':'new-password';$('#auth-message').textContent=''};
$('#auth-form').onsubmit=async e=>{e.preventDefault();if(!client)return;$('#submit-auth').disabled=true;$('#auth-message').textContent='';try{const email=$('#email').value.trim(),password=$('#password').value;const result=recovery?await client.auth.updateUser({password}):mode==='signup'?await client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}}):await client.auth.signInWithPassword({email,password});if(result.error)throw result.error;$('#password').value='';if(recovery){recovery=false;$('#auth-message').textContent='Passwort aktualisiert.';$('#auth-dialog').close()}else if(mode==='signup'&&!result.data.session){$('#auth-message').textContent='Prüfe dein E-Mail-Postfach und bestätige deine Anmeldung.'}else $('#auth-dialog').close()}catch{$('#auth-message').textContent='Das hat nicht geklappt. Prüfe deine Angaben und gegebenenfalls die Bestätigung deiner E-Mail-Adresse.'}finally{$('#submit-auth').disabled=false}};
$('#reset-password').onclick=async()=>{const email=$('#email').value.trim();if(!email||!$('#email').checkValidity()){$('#auth-message').textContent='Bitte zuerst eine gültige E-Mail-Adresse eingeben.';return}const {error:e}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});$('#auth-message').textContent=e?'Die Anfrage ist fehlgeschlagen. Bitte später erneut versuchen.':'Falls ein Konto existiert, erhältst du einen Link zum Zurücksetzen.'};
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{if(b.dataset.type==='saved'&&!user){openAuth();return}type=b.dataset.type;limit=30;document.querySelectorAll('[data-type]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()});['search','from','to','seat'].forEach(id=>$('#'+id).addEventListener('input',()=>{limit=30;render()}));$('#more').onclick=()=>{limit+=30;render()};
async function initAuth(){if(!config.supabaseUrl||!config.supabasePublishableKey)return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');client=createClient(config.supabaseUrl,config.supabasePublishableKey);client.auth.onAuthStateChange((event,session)=>{user=session?.user||null;$('#account').textContent=user?'Mein Konto':'Anmelden';if(event==='PASSWORD_RECOVERY'){recovery=true;openAuth();$('#auth-form').hidden=false;$('#email').closest('label').hidden=true;$('#email').required=false;$('#password').autocomplete='new-password';$('#submit-auth').textContent='Neues Passwort speichern';$('#switch-auth').hidden=true;$('#reset-password').hidden=true;$('#sign-out').hidden=true;$('#auth-title').textContent='Neues Passwort';}setTimeout(()=>loadBookmarks(),0)});}catch{error('Die Anmeldung ist momentan nicht erreichbar. Die Meldungsübersicht bleibt verfügbar.')}}
async function init(){try{const response=await fetch('./data/notices.json',{cache:'no-cache'});if(!response.ok)throw Error();const data=await response.json();notices=data.notices;$('#coverage').textContent=`Publikationen vom ${formatDate(data.coverageStart)} bis ${formatDate(data.coverageEnd)} · Kanton SO`;$('#updated').textContent='Datenstand: '+new Intl.DateTimeFormat('de-CH',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Zurich'}).format(new Date(data.updatedAt));$('#total').textContent=notices.length;[['new','HR01'],['changes','HR02'],['deleted','HR03']].forEach(([id,t])=>$('#'+id).textContent=notices.filter(n=>n.type===t).length);for(const seat of [...new Set(notices.map(n=>n.seat).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'de'))){const option=node('option',seat);option.value=seat;$('#seat').append(option)}render()}catch{error('Meldungen konnten nicht geladen werden. Bitte die Seite später erneut laden.');$('#result-count').textContent='Daten nicht verfügbar'}await initAuth()}init();
